  "implementation": "def solve(case):
    items = case['items']
    R = set(case['required_failure_items'])
    U = set(case['unresolved_without'])

    tests_count = 0

    def test(subset):
        nonlocal tests_count
        tests_count += 1
        s = set(subset)
        if R.issubset(s):
            if U.issubset(s):
                return 'fail'
            else:
                return 'unresolved'
        else:
            return 'pass'

    def split_list(lst, n):
        k, m = divmod(len(lst), n)
        subsets = []
        i = 0
        for j in range(n):
            size = k + (1 if j < m else 0)
            subsets.append(lst[i:i+size])
            i += size
        return subsets

    s = list(items)
    if len(s) == 0:
        return {'outcome': 'pass', 'tests': 0, 'minimal_failure': []}

    n = 2
    while n <= len(s):
        subsets = split_list(s, n)
        reduced = False
        for subset in subsets:
            complement = [x for x in s if x not in set(subset)]
            outcome = test(complement)
            if outcome == 'fail':
                s = complement
                n = max(n - 1, 2)
                reduced = True
                break
            # else continue to next subset
        if not reduced:
            if n == len(s):
                break
            n = min(2 * n, len(s))

    minimal_failure = s
    outcome = 'fail' if minimal_failure else 'pass'
    return {'outcome': outcome, 'tests': tests_count, 'minimal_failure': minimal_failure}
